<!doctype html>
<html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Area · Nodexa</title>
<style>
:root{--bg:#090b10;--panel:#11151d;--panel2:#171c27;--line:#252b39;--text:#f6f7fb;--muted:#929bad;--accent:#745cff;--ok:#39d98a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{padding:28px 18px;border-right:1px solid var(--line);background:#0d1016}.brand{font-size:24px;font-weight:900;letter-spacing:-1px;margin:0 10px 34px}.brand span{color:var(--accent)}.nav a{display:flex;padding:12px 14px;margin:5px 0;border-radius:10px;color:#b8c0ce;text-decoration:none;font-weight:650}.nav a:hover,.nav a.active{background:#1a1e2b;color:#fff}.main{padding:34px;max-width:1450px;width:100%;margin:auto}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:30px}.top h1{margin:0;font-size:30px}.muted{color:var(--muted)}.account{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:10px 14px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px}.stat strong{display:block;font-size:28px;margin-top:8px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:18px}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.section-title h2{font-size:18px;margin:0}.btn{display:inline-block;background:var(--accent);color:#fff;text-decoration:none;border-radius:9px;padding:9px 13px;font-weight:700}.service{display:grid;grid-template-columns:1.5fr 1fr auto;align-items:center;padding:15px 0;border-top:1px solid var(--line)}.service:first-of-type{border-top:0}.status{color:var(--ok);font-weight:700}.empty{padding:28px 4px;color:var(--muted)}.quick{display:grid;gap:10px}.quick a{padding:14px;border-radius:10px;background:var(--panel2);color:#e6e8ee;text-decoration:none}.table-row{display:grid;grid-template-columns:1fr auto;gap:12px;padding:12px 0;border-top:1px solid var(--line)}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{display:none}.main{padding:20px}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.service{grid-template-columns:1fr;gap:5px}}@media(max-width:520px){.stats{grid-template-columns:1fr}.top{align-items:flex-start;gap:15px;flex-direction:column}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">NOD<span>EXA</span></div><nav class="nav"><a class="active" href="/client">Dashboard</a><a href="/client#services">Mine services</a><a href="/store">Bestil service</a><a href="/client#invoices">Fakturaer</a><a href="/client#tickets">Support tickets</a><a href="/account">Min konto</a><a href="/">Serverpanel</a></nav></aside><main class="main"><div class="top"><div><h1>Client Area</h1><div class="muted">Velkommen tilbage, {{ $user->username ?? $user->name ?? $user->email }}</div></div><div class="account">{{ $user->email }}</div></div><section class="stats"><div class="card stat"><span class="muted">Aktive services</span><strong>{{ $services->count() }}</strong></div><div class="card stat"><span class="muted">Ubetalte fakturaer</span><strong>{{ $invoices->where('status','unpaid')->count() }}</strong></div><div class="card stat"><span class="muted">Åbne tickets</span><strong>{{ $tickets->where('status','!=','closed')->count() }}</strong></div><div class="card stat"><span class="muted">Konto</span><strong style="font-size:18px">Aktiv</strong></div></section><div class="grid"><section class="card" id="services"><div class="section-title"><h2>Mine services</h2><a class="btn" href="/store">Bestil ny</a></div>@forelse($services as $service)<div class="service"><div><strong>{{ $service->name ?? ('Service #'.$service->id) }}</strong><div class="muted">Server #{{ $service->id }}</div></div><div class="status">● {{ ucfirst($service->status ?? 'active') }}</div><a class="btn" href="/">Administrér</a></div>@empty<div class="empty">Du har ingen aktive services endnu.</div>@endforelse</section><aside class="card"><div class="section-title"><h2>Hurtige handlinger</h2></div><div class="quick"><a href="/store">＋ Bestil en service</a><a href="/client#tickets">◎ Opret support ticket</a><a href="/client#invoices">▤ Se fakturaer</a><a href="/account">⚙ Kontoindstillinger</a></div></aside><section class="card" id="invoices"><div class="section-title"><h2>Seneste fakturaer</h2></div>@forelse($invoices as $invoice)<div class="table-row"><span>Faktura #{{ $invoice->id }}</span><strong>{{ ucfirst($invoice->status ?? 'ukendt') }}</strong></div>@empty<div class="empty">Ingen fakturaer endnu.</div>@endforelse</section><section class="card" id="tickets"><div class="section-title"><h2>Support</h2></div>@forelse($tickets as $ticket)<div class="table-row"><span>{{ $ticket->subject ?? ('Ticket #'.$ticket->id) }}</span><strong>{{ ucfirst($ticket->status ?? 'open') }}</strong></div>@empty<div class="empty">Ingen åbne support tickets.</div>@endforelse</section></div></main></div></body></html>